export function en(v: number) {
  return v.toLocaleString('en-US')
}

export function fmtP(n: number) {
  if (n >= 1e9) return (n / 1e9).toFixed(1) + 'B'
  if (n >= 1e6) return (n / 1e6).toFixed(n >= 1e7 ? 1 : 2) + 'M'
  if (n >= 1e3) return (n / 1e3).toFixed(1) + 'K'
  return String(n)
}

export function avg(a: number[]) {
  return a.reduce((x, y) => x + y, 0) / a.length
}

export function hashH(t: number, k: number) {
  const order = ORD8[k]
  const m = MULTS[k]
  const parts: [number, number][] = []
  let x = 0n
  for (let j = 0; j < order; j++) {
    const p = t - (order - 1) + j
    const id = p < 0 ? 0 : HX_IDS[p]
    parts.push([id, m[j]])
    x ^= BigInt(id) * BigInt(m[j])
  }
  return { x, parts }
}

export function rowOf(t: number, k: number, table: number) {
  return Number(hashH(t, k).x % BigInt(table))
}

export function randColl(n: number, m: number) {
  return 1 - (m * (1 - Math.pow(1 - 1 / m, n))) / n
}

export function mix(v: number) {
  const a = [250, 249, 245]
  const b = [217, 119, 87]
  return `rgb(${a.map((x, i) => Math.round(x + (b[i] - x) * v)).join(',')})`
}

export function fin(r: Run) {
  return r.curve[r.curve.length - 1]
}
